<script setup>
import {computed,watch,ref} from 'vue';import{Head,Link,useForm,router}from'@inertiajs/vue3';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';import{useFamilyCopy}from'@/lib/family';
const p=defineProps({nurseryCode:String,inviteUrl:String,children:Array,access:Array,messages:Array,announcements:Array,care:Array,incidents:Array,absences:Array,reviewFilters:Object});const{l,mood,t}=useFamilyCopy();const publishErrors=ref({});const reviewChild=ref(p.reviewFilters?.child_id||''),reviewDate=ref(p.reviewFilters?.date||'');
function filterReview(){router.get('/families',{review_child:reviewChild.value||undefined,review_date:reviewDate.value||undefined},{preserveState:true,preserveScroll:true});}
const invite=useForm({child_id:'',guardian_id:'',email:'',pickup_person_id:'',share_billing:false,identity_confirmed:false});
const selected=computed(()=>p.children.find(c=>c.id===Number(invite.child_id)));
watch(()=>invite.child_id,()=>{invite.guardian_id='';invite.email='';invite.pickup_person_id='';invite.identity_confirmed=false;});watch(()=>invite.guardian_id,()=>{invite.email=selected.value?.guardians.find(g=>g.id===Number(invite.guardian_id))?.email||'';invite.identity_confirmed=false;});
const reply=useForm({family_account_id:'',child_id:'',body:''});const announcement=useForm({title:'',body:''});const task=useForm({child_id:'',title:'',due_date:''});
function replyTo(m){reply.family_account_id=m.family_account_id;reply.child_id=m.child_id;document.getElementById('family-reply')?.scrollIntoView({behavior:'smooth'});}
function publish(type,item){if(!item.family_visible&&!confirm(l('سيظهر النص المعروض كاملاً للحسابات التي اعتمدتها لهذا الطفل. هل راجعته؟','The full text shown will be visible to the families approved for this child. Have you reviewed it?')))return;router.post(`/families/publish/${type}/${item.id}`,{visible:!item.family_visible,review_hash:item.review_hash},{preserveScroll:true,onError:()=>publishErrors.value[type+item.id]=l('تغير السجل أو تعذر تأكيد مراجعته. حدّث الصفحة واقرأ النص الحالي مرة أخرى قبل المشاركة.','The record changed or review proof is missing. Refresh and review the current text before sharing.'),onSuccess:()=>publishErrors.value[type+item.id]=''});}
function revoke(a){if(confirm(l('إلغاء وصول هذا الحساب لهذا الطفل فوراً؟','Revoke this account’s access to this child now?')))router.post(`/families/access/${a.id}/revoke`,{},{preserveScroll:true});}
</script>
<template><Head :title="l('تواصل الأسرة','Family connections')"/><AuthenticatedLayout><div class="family-main"><header class="family-heading"><p class="eyebrow">{{l('صلة بين البيت والحضانة','Home and nursery, connected')}}</p><h1>{{l('مساحة الأسرة','Family space')}}</h1><p class="family-muted">{{l('اعتمد كل علاقة بنفسك. لا تنشر السجلات القديمة تلقائياً، ولا ترسل هذه الصفحة رسائل خارج النظام.','Approve each relationship explicitly. Existing records are not published automatically. This page does not send messages outside Nursery.')}}</p><p class="family-muted">{{l('رمز الحضانة','Nursery code')}}: <strong dir="ltr">{{nurseryCode}}</strong> · <Link href="/family/login" class="family-text-link">{{l('دخول الأسرة','Family sign-in')}}</Link></p><nav class="flex flex-wrap gap-3 mt-4"><a href="#family-sharing-review" class="family-secondary">{{l('مراجعة المشاركة','Sharing review')}}</a><a href="#family-reply" class="family-secondary">{{l('الرد على الأسر','Family replies')}}</a></nav></header>
<section v-if="inviteUrl" class="family-card mb-6"><h2>{{l('الدعوة جاهزة لمدة ٢٤ ساعة','Invitation ready for 24 hours')}}</h2><p class="family-muted">{{l('انقلها للشخص الذي تحققت منه فقط، بقناة آمنة. هذا الرابط يمنح وصولاً، ولا يعرض مرة أخرى بعد مغادرة الصفحة.','Share only with the person whose identity you verified, through a secure channel. This link grants access and is not shown again after leaving this page.')}}</p><p class="family-invite" dir="ltr">{{inviteUrl}}</p></section>
<div class="family-manage-grid"><section class="family-card"><h2>{{l('دعوة معتمدة','Approve a family invitation')}}</h2><form class="family-form" @submit.prevent="invite.post('/families/invite',{preserveScroll:true,onSuccess:()=>invite.reset()})"><label>{{l('الطفل','Child')}}<select v-model="invite.child_id" required><option value="" disabled>{{l('اختر طفلاً','Choose a child')}}</option><option v-for="c in children" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{l('ولي الأمر المرتبط بالطفل','Linked guardian')}}<select v-model="invite.guardian_id" required><option value="" disabled>{{l('اختر ولي أمر','Choose a guardian')}}</option><option v-for="g in selected?.guardians||[]" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label>{{l('بريد ولي الأمر بعد التحقق، سيحفظ في سجله','Verified guardian email, saved to their record')}}<input v-model="invite.email" type="email" dir="ltr" required/></label><label>{{l('صلاحية رمز الاستلام، اختيارية','Pickup-code permission, optional')}}<select v-model="invite.pickup_person_id"><option value="">{{l('بدون رمز استلام','No pickup code')}}</option><option v-for="a in selected?.pickups||[]" :key="a.id" :value="a.id">{{a.name}}</option></select></label><p class="family-muted">{{l('اختيار مستلم لا ينشئ تفويضاً جديداً. يجب أن يكون هذا الشخص هو صاحب حساب الأسرة المقصود، ومفوضاً بالفعل لهذا الطفل.','Choosing a pickup person does not create authorization. The selected person must be this family account holder and already authorized for this child.')}}</p><label class="check"><input v-model="invite.share_billing" type="checkbox"/>{{l('السماح بالاطلاع على الفواتير الصادرة والإيصالات','Allow issued invoices and recorded-payment receipts')}}</label><label class="check"><input v-model="invite.identity_confirmed" type="checkbox" required/>{{l('تحققت من هوية هذا الشخص وبريده وأحقيته في الاطلاع على بيانات هذا الطفل، ومن مطابقة مستلم الرمز إن اخترته.','I verified this person’s identity, email and right to view this child’s information, and the pickup-person match if selected.')}}</label><p v-for="e in invite.errors" :key="e" class="family-error">{{e}}</p><button class="family-primary" :disabled="invite.processing">{{l('إنشاء رابط الدعوة','Create invitation link')}}</button></form></section>
<section class="family-card"><h2>{{l('الحسابات المرتبطة','Linked family access')}}</h2><div v-for="a in access" :key="a.id" class="family-ledger"><strong>{{a.first_name}} {{a.last_name}}</strong><p>{{a.name}}</p><p dir="ltr">{{a.email}}</p><p>{{a.share_billing?l('الرسوم متاحة','Billing shared'):l('دون رسوم','No billing access')}}</p><button v-if="a.active" class="family-secondary" @click="revoke(a)">{{l('إلغاء وصول الطفل','Revoke child access')}}</button><span v-else class="family-muted">{{l('الوصول ملغى','Access revoked')}}</span></div><p v-if="!access.length" class="family-muted">{{l('لم يفعل أي حساب دعوته بعد.','No family has activated an invitation yet.')}}</p></section></div>
<h2 class="family-section-title">{{l('مراسلات الأسرة','Family conversations')}}</h2><div class="family-manage-grid"><section class="family-card"><article v-for="m in messages" :key="m.id" class="family-message" :class="{team:m.staff_id}"><strong>{{m.first_name}} {{m.last_name}} · {{m.name}}</strong><small class="block">{{m.staff_id?l('رد الفريق','Team reply'):l('من الأسرة','From family')}} · {{m.created_at}}</small><p class="family-copy">{{m.body}}</p><button class="family-secondary" @click="replyTo(m)">{{l('رد على هذه الأسرة','Reply to this family')}}</button></article><p v-if="!messages.length" class="family-muted">{{l('لا توجد رسائل بعد.','No messages yet.')}}</p></section><section class="family-card" id="family-reply"><h2>{{l('رد للحساب المحدد','Reply to the selected account')}}</h2><p class="family-muted">{{l('اختر رسالة أولاً. الرد داخل مساحة الأسرة فقط، وليس واتساب أو إيميلاً.','Choose a message first. Replies stay inside Family Space, not WhatsApp or email.')}}</p><form class="family-form" @submit.prevent="reply.post('/families/reply',{preserveScroll:true,onSuccess:()=>reply.reset('body')})"><label>{{l('الرد','Reply')}}<textarea v-model="reply.body" maxlength="4000" rows="4" required/></label><p v-for="e in reply.errors" :key="e" class="family-error">{{e}}</p><button class="family-primary" :disabled="!reply.family_account_id||reply.processing">{{l('إرسال الرد','Send reply')}}</button></form><h2 class="mt-8">{{l('إعلان لكل الأسر المعتمدة','Announcement to approved families')}}</h2><form class="family-form" @submit.prevent="announcement.post('/families/announcements',{preserveScroll:true,onSuccess:()=>announcement.reset()})"><label>{{l('العنوان','Title')}}<input v-model="announcement.title" maxlength="150" required/></label><label>{{l('النص، بدون بيانات طفل بعينه','Text, without an individual child’s data')}}<textarea v-model="announcement.body" maxlength="4000" rows="4" required/></label><p v-for="e in announcement.errors" :key="e" class="family-error">{{e}}</p><button class="family-primary" :disabled="announcement.processing">{{l('نشر داخل مساحة الأسرة','Publish in Family Space')}}</button></form></section></div>
<h2 id="family-sharing-review" class="family-section-title scroll-mt-24">{{l('مراجعة قبل المشاركة','Review before sharing')}}</h2><p class="family-muted mb-5">{{l('النص الظاهر هنا هو ما سيصل للأسرة المعتمدة. تعديل اليومية يخفيها حتى تعيد مراجعتها ومشاركتها. لا تشارك ملاحظات فريق داخلية أو معلومات عن طفل آخر.','The text below is what approved families will see. Editing a care log hides it until reviewed and shared again. Do not share internal team notes or information about another child.')}}</p><form class="family-card family-range mb-6" @submit.prevent="filterReview"><label>{{l('تصفية مراجعة اليوميات والحوادث بالطفل','Filter care and incident review by child')}}<select v-model="reviewChild" :aria-label="l('تصفية مراجعة اليوميات والحوادث بالطفل','Filter care and incident review by child')" class="search-field"><option value="">{{l('كل الأطفال','All children')}}</option><option v-for="c in children" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{l('يوم محدد، اختياري','Specific day, optional')}}<input v-model="reviewDate" type="date"/></label><button class="family-secondary">{{l('عرض للمراجعة','Show for review')}}</button><p class="family-muted w-full">{{l('آخر ٣٠ سجلاً من كل نوع. اختر طفلاً أو يوماً للوصول إلى السجلات الأقدم.','Latest 30 entries of each type. Choose a child or day to find older records.')}}</p></form><div class="family-manage-grid"><section class="family-card"><h2>{{l('اليوميات','Care updates')}}</h2><article v-for="a in care" :key="a.id" class="family-ledger"><strong>{{a.first_name}} {{a.last_name}} · {{a.date}}</strong><p class="family-copy">{{[a.meals,a.naps,mood(a.mood),a.activities,a.notes].filter(Boolean).join('\n')}}</p><button class="family-secondary" @click="publish('care',a)">{{a.family_visible?l('إخفاء من الأسرة','Hide from family'):l('مشاركة مع الأسرة','Share with family')}}</button><p v-if="publishErrors['care'+a.id]" role="alert" class="family-error mt-3">{{publishErrors['care'+a.id]}}</p></article></section><section class="family-card"><h2>{{l('الحوادث','Incidents')}}</h2><article v-for="a in incidents" :key="a.id" class="family-ledger"><strong>{{a.first_name}} {{a.last_name}}</strong><small class="block">{{a.occurred_at}} · {{t(a.severity)}}</small><p class="family-copy">{{a.description}}</p><button class="family-secondary" @click="publish('incident',a)">{{a.family_visible?l('إخفاء من الأسرة','Hide from family'):l('مشاركة مع الأسرة','Share with family')}}</button><p v-if="publishErrors['incident'+a.id]" role="alert" class="family-error mt-3">{{publishErrors['incident'+a.id]}}</p></article></section></div>
<div class="family-manage-grid mt-6"><section class="family-card"><h2>{{l('مهمة للأسرة','A task for the family')}}</h2><form class="family-form" @submit.prevent="task.post('/families/tasks',{preserveScroll:true,onSuccess:()=>task.reset()})"><label>{{l('الطفل','Child')}}<select v-model="task.child_id" required><option value="" disabled>{{l('اختر طفلاً','Choose a child')}}</option><option v-for="c in children" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{l('المطلوب','Task')}}<input v-model="task.title" maxlength="200" required/></label><label>{{l('موعد اختياري','Optional due date')}}<input v-model="task.due_date" type="date"/></label><p v-for="e in task.errors" :key="e" class="family-error">{{e}}</p><button class="family-primary" :disabled="task.processing">{{l('إضافة المهمة','Add task')}}</button></form></section><section class="family-card"><h2>{{l('إخطارات غياب مخطط','Planned absence notices')}}</h2><article v-for="a in absences" :key="a.id" class="family-ledger"><strong>{{a.first_name}} {{a.last_name}}</strong><p>{{a.starts_on}} · {{a.ends_on}}</p><p v-if="a.cancelled_at" class="family-muted">{{l('ألغت الأسرة هذا الإخطار','Family cancelled this notice')}} · {{a.cancelled_at}}</p><p class="family-copy">{{a.reason}}</p></article><p v-if="!absences.length" class="family-muted">{{l('لا توجد إخطارات.','No notices.')}}</p></section></div></div></AuthenticatedLayout></template>
